window.SCHOOL_LISTENING={"../assets/media/69ddeaa8cf80e1e3c08e4c10d4393abc7e2a1b92dc25554f2b6c4275ea987f5f.mp3":[{"id":"PPT_69ddeaa8cf80e1e3","audioId":"PPT_69ddeaa8cf80e1e3","title":"Book 2 · Unit 1 · LS · PREPARATION FOR SPEAKING","subtitle":"PREPARATION FOR SPEAKING · source slide 177","duration":45.51,"cues":[{"start":0,"end":1.94,"text":"one .five","coverage":1},{"start":3,"end":3.8,"text":"one.","coverage":1},{"start":5.38,"end":10.08,"text":"I'd like to talk about the city of Vancouver in British Columbia,","coverage":1},{"start":10.48,"end":11,"text":"Canada.","coverage":1},{"start":13.52,"end":14.32,"text":"two.","coverage":1},{"start":15.58,"end":16.54,"text":"First of all,","coverage":1},{"start":16.94,"end":18.98,"text":"let's look at some of the positives.","coverage":1},{"start":21.38,"end":22.18,"text":"three.","coverage":1},{"start":23.56,"end":28.06,"text":"I'd also like to talk about some disadvantages of parks in Vancouver.","coverage":1},{"start":30.62,"end":31.42,"text":"four.","coverage":1},{"start":32.66,"end":33.18,"text":"Finally,","coverage":1},{"start":33.62,"end":38.94,"text":"while I think these disadvantages mean that some people would not want to visit Vancouver,","coverage":1},{"start":39.62,"end":43.66,"text":"I personally feel that most people would enjoy Vancouver.","coverage":1}],"file":"176a4c9f056567227e25.js","track":0,"media":"../assets/media/69ddeaa8cf80e1e3c08e4c10d4393abc7e2a1b92dc25554f2b6c4275ea987f5f.mp3"}],"../assets/media/871ce69611556a6430fcfe65b2ba57b291bd173da19d2dbbed18a5f4c9e8ffd5.mp3":[{"id":"PPT_871ce69611556a64","audioId":"PPT_871ce69611556a64","title":"Book 2 · Unit 1 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 59","duration":230.4,"cues":[{"start":0,"end":2.3,"text":"one .two","coverage":1},{"start":3.02,"end":5.46,"text":"Welcome to the Travel Podcast.","coverage":1},{"start":5.96,"end":6.74,"text":"I'm James.","coverage":1},{"start":7.44,"end":12.86,"text":"I'm here with Susie and today we're looking at unusual places where people actually live.","coverage":1},{"start":13.52,"end":14.98,"text":"Susie, when you travelled,","coverage":1},{"start":15.44,"end":19.18,"text":"did you see any interesting or strange homes around the world?","coverage":1},{"start":20.18,"end":23.06,"text":"Well, it depends what you mean by strange.","coverage":1},{"start":23.06,"end":25.38,"text":"I live in a detached house,","coverage":1},{"start":25.98,"end":29,"text":"so the apartment buildings in New York, for example,","coverage":1},{"start":29.54,"end":31.34,"text":"seem pretty strange to me.","coverage":1},{"start":32.28,"end":35.76,"text":"I really mean places that very few people know about.","coverage":1},{"start":36.76,"end":38.04,"text":"Oh, I see.","coverage":1},{"start":38.64,"end":39.9,"text":"Um, well,","coverage":1},{"start":40.34,"end":42.74,"text":"when I was on holiday last year in Peru,","coverage":1},{"start":43.12,"end":46.48,"text":"I saw a really old city made out of mud.","coverage":1},{"start":47.58,"end":49.88,"text":"You could say that is interesting.","coverage":1},{"start":51.12,"end":53.5,"text":"Yes, that is very interesting.","coverage":1},{"start":54.44,"end":58.3,"text":"And so are the cave houses in the lowest part of China.","coverage":1},{"start":59.64,"end":60.24,"text":"Lowest?","coverage":1},{"start":60.78,"end":62.04,"text":"Where is that in China?","coverage":1},{"start":63.1,"end":64.5,"text":"It's in the north part.","coverage":1},{"start":65.14,"end":66.18,"text":"Take a look at the picture.","coverage":1},{"start":66.96,"end":68.08,"text":"Do you see these caves?","coverage":1},{"start":68.96,"end":70.54,"text":"Well, they're actually houses.","coverage":1},{"start":71.44,"end":74.12,"text":"Some people think the cave houses look strange.","coverage":1},{"start":74.96,"end":77.38,"text":"But millions of people live in these houses.","coverage":1},{"start":78.1,"end":79.98,"text":"Many houses are below the ground.","coverage":1},{"start":80.92,"end":83.38,"text":"Other houses are caves in the side of hills.","coverage":1},{"start":84,"end":86.48,"text":"They made them out of the soil and rock.","coverage":1},{"start":87.24,"end":90.32,"text":"People started to live in them four ,000 years ago.","coverage":1},{"start":90.94,"end":92.88,"text":"Wow, that's ancient.","coverage":1},{"start":93.52,"end":94.68,"text":"Where is it exactly?","coverage":1},{"start":95.7,"end":99.28,"text":"It's about one ,000 kilometres west of the capital, Beijing.","coverage":1},{"start":99.9,"end":101.24,"text":"I'd love to go there.","coverage":1},{"start":102,"end":105.52,"text":"Actually, when I was younger, I went to Cappadocia in Turkey.","coverage":1},{"start":105.52,"end":107.38,"text":"It was fantastic.","coverage":1},{"start":108.14,"end":109.8,"text":"There are cave houses there too.","coverage":1},{"start":110.4,"end":112.84,"text":"It's in Anatolia in the centre of Turkey.","coverage":1},{"start":113.4,"end":114.08,"text":"Take a look.","coverage":1},{"start":114.74,"end":116.68,"text":"The buildings look like mushrooms.","coverage":1},{"start":117.96,"end":119.58,"text":"Interesting place, isn't it?","coverage":1},{"start":119.92,"end":123.86,"text":"The caves formed from rock more than eight ,000 years ago.","coverage":1},{"start":124.74,"end":127.84,"text":"People changed them into homes during the Roman period.","coverage":1},{"start":128.54,"end":130.46,"text":"Some people still live there now.","coverage":1},{"start":131.2,"end":131.68,"text":"Now?","coverage":1},{"start":132.26,"end":133.28,"text":"That's amazing.","coverage":1},{"start":133.92,"end":136.68,"text":"But did you know that some people live on bridges?","coverage":1},{"start":137.38,"end":138.78,"text":"Look at these two photos.","coverage":1},{"start":139.72,"end":139.85,"text":"Oh","coverage":1},{"start":139.85,"end":140.44,"text":"yeah,","coverage":1},{"start":141.1,"end":143.08,"text":"I think I recognise this bridge.","coverage":1},{"start":143.82,"end":146.16,"text":"It's beautiful and it looks very old.","coverage":1},{"start":147,"end":149.06,"text":"It's in Italy, isn't it?","coverage":1},{"start":149.92,"end":151.12,"text":"Is it in Rome?","coverage":1},{"start":152.14,"end":153.48,"text":"Well, it is in Italy.","coverage":1},{"start":154.02,"end":155.8,"text":"It's called the Ponte Vecchio,","coverage":1},{"start":156.32,"end":158.88,"text":"but it's actually in Florence, north of Rome.","coverage":1},{"start":159.56,"end":162.18,"text":"They built the bridge in 1345.","coverage":1},{"start":162.5,"end":166.74,"text":"There was another bridge there before, but an accident destroyed it.","coverage":1},{"start":167.18,"end":170.4,"text":"So they made this one and people started to live there.","coverage":1},{"start":171.06,"end":172.86,"text":"It's amazing, isn't it?","coverage":1},{"start":173.86,"end":175.48,"text":"Yes, it is.","coverage":1},{"start":176.4,"end":179.3,"text":"But the houses in the other picture look newer.","coverage":1},{"start":180.22,"end":182.48,"text":"Yeah, those are Palafitos,","coverage":1},{"start":182.92,"end":184.38,"text":"stilt houses in Chile.","coverage":1},{"start":185.04,"end":185.38,"text":"Where?","coverage":1},{"start":186.06,"end":187.3,"text":"You know, Chile,","coverage":1},{"start":187.78,"end":188.74,"text":"in South America.","coverage":1},{"start":189.74,"end":190.82,"text":"Oh, of course.","coverage":1},{"start":191.5,"end":193.14,"text":"Are they on a bridge too?","coverage":1},{"start":194.24,"end":200.44,"text":"No, they build these houses over lakes or over the edge of the sea, not over rivers.","coverage":1},{"start":201.04,"end":202.1,"text":"They're on stilts.","coverage":1},{"start":203.2,"end":206.82,"text":"People started to build these over 100 years ago.","coverage":1},{"start":207.54,"end":210.98,"text":"The people fish in the lake or the sea near their houses.","coverage":1},{"start":212.42,"end":212.86,"text":"Really?","coverage":1},{"start":213.52,"end":215.62,"text":"So these houses aren't ancient.","coverage":1},{"start":216.7,"end":217.96,"text":"Do many people live there?","coverage":1},{"start":218.92,"end":219.44,"text":"Yes,","coverage":1},{"start":219.88,"end":222.14,"text":"hundreds of people still live like this.","coverage":1},{"start":223.16,"end":223.64,"text":"Well,","coverage":1},{"start":224.04,"end":226.4,"text":"they make my house look really boring.","coverage":1},{"start":227.82,"end":228.54,"text":"Mine too.","coverage":1}],"file":"2a60d18ed7691fd3eb57.js","track":0,"media":"../assets/media/871ce69611556a6430fcfe65b2ba57b291bd173da19d2dbbed18a5f4c9e8ffd5.mp3"}],"../assets/media/cd1261fe09fd46e2626e133e970547d2bf8e70d0aba6881ead110fdbecc4be2d.mp3":[{"id":"PPT_cd1261fe09fd46e2","audioId":"PPT_cd1261fe09fd46e2","title":"Book 2 · Unit 1 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 90","duration":64.57,"cues":[{"start":0,"end":2.22,"text":"one .four","coverage":1},{"start":3.36,"end":4.16,"text":"one.","coverage":1},{"start":5.88,"end":8.68,"text":"Obviously Stanley Park is a large park.","coverage":1},{"start":10.92,"end":11.72,"text":"two.","coverage":1},{"start":12.96,"end":13.64,"text":"In fact,","coverage":1},{"start":14,"end":16.6,"text":"because it is located in the city of Vancouver,","coverage":1},{"start":17.12,"end":20.56,"text":"it is the third largest urban park in North America.","coverage":1},{"start":23.02,"end":23.74,"text":"three.","coverage":1},{"start":25.12,"end":26.14,"text":"As we know,","coverage":1},{"start":26.46,"end":29.58,"text":"lots of trees help clean the city air.","coverage":1},{"start":32.18,"end":32.9,"text":"four.","coverage":1},{"start":34.14,"end":34.66,"text":"Finally,","coverage":1},{"start":35.22,"end":42.56,"text":"while I think these disadvantages might mean that some people would not want to visit Vancouver...","coverage":1},{"start":43.84,"end":44.7,"text":"five.","coverage":1},{"start":46.08,"end":50.24,"text":"I personally feel that most people would enjoy Vancouver.","coverage":1},{"start":52.8,"end":53.66,"text":"six.","coverage":1},{"start":54.84,"end":55.9,"text":"In my opinion,","coverage":1},{"start":56.36,"end":62.74,"text":"being close to nature and having a healthy city are worth paying a little more money for.","coverage":1}],"file":"58ede0f2cfe1b5a9c388.js","track":0,"media":"../assets/media/cd1261fe09fd46e2626e133e970547d2bf8e70d0aba6881ead110fdbecc4be2d.mp3"}],"../assets/media/863d883603a445809d3bb35ce4a38a4fe3c3cd19811d44f021742caaf5d25ca9.mp3":[{"id":"PPT_863d883603a44580","audioId":"PPT_863d883603a44580","title":"Book 2 · Unit 1 · LS · PREPARATION FOR SPEAKING","subtitle":"PREPARATION FOR SPEAKING · source slide 184","duration":10.14,"cues":[{"start":3.14,"end":8.22,"text":"I'd like to talk about the city of Vancouver in British Columbia, Canada.","coverage":1}],"file":"8b6bc96cbed45f6a80a3.js","track":0,"media":"../assets/media/863d883603a445809d3bb35ce4a38a4fe3c3cd19811d44f021742caaf5d25ca9.mp3"}],"../assets/media/66d3b4a03f7cbe0567827c7b7c33023d58411f416ccf2ad68d6d2e0da63720c2.mp3":[{"id":"PPT_66d3b4a03f7cbe05","audioId":"PPT_66d3b4a03f7cbe05","title":"Book 2 · Unit 1 · LS · PREPARATION FOR SPEAKING","subtitle":"PREPARATION FOR SPEAKING · source slide 185","duration":8.41,"cues":[{"start":0,"end":1.74,"text":"one .seven","coverage":1},{"start":3.26,"end":6.42,"text":"First of all, let's look at some of the positives.","coverage":1}],"file":"91a4b4d47a4ce7b2518f.js","track":0,"media":"../assets/media/66d3b4a03f7cbe0567827c7b7c33023d58411f416ccf2ad68d6d2e0da63720c2.mp3"}],"../assets/media/91c2d6e131422bd80badd663f3864731f37172b73aef2c380d0cec1a6cf488bc.mp3":[{"id":"PPT_91c2d6e131422bd8","audioId":"PPT_91c2d6e131422bd8","title":"Book 2 · Unit 1 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 85","duration":299.15,"cues":[{"start":0,"end":1.52,"text":"one .three","coverage":1},{"start":2.82,"end":4.5,"text":"OK, everyone.","coverage":1},{"start":5.22,"end":8.76,"text":"Today we are talking about interesting places.","coverage":1},{"start":9.4,"end":15.12,"text":"I'd like to talk about the city of Vancouver in British Columbia,","coverage":1},{"start":15.42,"end":15.74,"text":"Canada.","coverage":1},{"start":16.72,"end":20.28,"text":"It's one of the most beautiful cities in the world.","coverage":1},{"start":21.44,"end":24.52,"text":"We often think cities are urban areas,","coverage":1},{"start":25.12,"end":27.64,"text":"with traffic and modern buildings.","coverage":1},{"start":28.46,"end":33.42,"text":"We don't usually think cities have woods, lakes and fields,","coverage":1},{"start":34.18,"end":37.08,"text":"but Vancouver is a green city,","coverage":1},{"start":37.74,"end":41.8,"text":"a place that's good to live in because it has clean air,","coverage":1},{"start":42.16,"end":43.9,"text":"water and land.","coverage":1},{"start":45,"end":50.52,"text":"Vancouver has the best parts of green forests and city life.","coverage":1},{"start":51.36,"end":55.76,"text":"I would like to talk about some of the history of Vancouver,","coverage":1},{"start":56.7,"end":62.26,"text":"as well as some of the advantages and disadvantages of this green city.","coverage":1},{"start":63.56,"end":64.16,"text":"Vancouver,","coverage":1},{"start":64.56,"end":65.2,"text":"originally,","coverage":1},{"start":65.76,"end":77.36,"text":"was a place where the native people of the area lived and traded for thousands of years before Europeans came to live there in the 1800s.","coverage":1},{"start":78.2,"end":78.7,"text":"Then,","coverage":1},{"start":79.16,"end":80.6,"text":"in 1886,","coverage":1},{"start":81.1,"end":82.78,"text":"at the first city meeting,","coverage":1},{"start":83.62,"end":92.54,"text":"the people of Vancouver asked the national government to give the city one thousand acres to use as a park.","coverage":1},{"start":93.94,"end":98.58,"text":"They got the land from the government and started Stanley Park.","coverage":1},{"start":98.58,"end":107.1,"text":"This was the start of Vancouver becoming a green city with many parks and beautiful views.","coverage":1},{"start":108.32,"end":114.54,"text":"But being a green city with lots of parks has both advantages and disadvantages.","coverage":1},{"start":115.84,"end":118.8,"text":"First of all, let's look at some of the positives.","coverage":1},{"start":119.98,"end":120.66,"text":"Obviously,","coverage":1},{"start":121.24,"end":123.26,"text":"Stanley Park is a large park.","coverage":1},{"start":123.26,"end":127.22,"text":"In fact, because it is located in the city of Vancouver,","coverage":1},{"start":127.88,"end":131.86,"text":"it is the third largest urban park in North America.","coverage":1},{"start":132.98,"end":134.66,"text":"It has many gardens,","coverage":1},{"start":135.24,"end":136.24,"text":"walking paths,","coverage":1},{"start":136.72,"end":141.24,"text":"trees and even animals such as bald eagles,","coverage":1},{"start":141.6,"end":143.48,"text":"coyotes and seals.","coverage":1},{"start":144.82,"end":149.54,"text":"As we know, lots of trees help clean the city air.","coverage":1},{"start":149.54,"end":150.96,"text":"Also,","coverage":1},{"start":151.54,"end":156.52,"text":"lots of parks give people many places to walk so they're healthier.","coverage":1},{"start":157.68,"end":161.16,"text":"Since Vancouver is near the mountains and the ocean,","coverage":1},{"start":161.8,"end":167.2,"text":"people can enjoy the outdoors easily during the warm, sunny summers.","coverage":1},{"start":168.4,"end":170.72,"text":"When people go to Stanley Park,","coverage":1},{"start":171.22,"end":175.64,"text":"they can enjoy ancient trees as they walk near the ocean.","coverage":1},{"start":175.64,"end":179.52,"text":"Or they can have fun by Beaver Lake,","coverage":1},{"start":179.84,"end":181.54,"text":"which, like Stanley Park,","coverage":1},{"start":182.12,"end":187.94,"text":"helps make Vancouver one of the healthiest and cleanest cities in the world.","coverage":1},{"start":189.38,"end":194.12,"text":"I'd also like to talk about some disadvantages of parks in Vancouver.","coverage":1},{"start":195.34,"end":198.36,"text":"Space in a city is very important.","coverage":1},{"start":198.36,"end":205.52,"text":"Having many parks means that people have less space to build houses and apartments.","coverage":1},{"start":206.82,"end":211.1,"text":"Because Vancouver is located between the mountains and the ocean,","coverage":1},{"start":211.82,"end":214.18,"text":"there's not much room for new buildings.","coverage":1},{"start":215.02,"end":217.92,"text":"This makes Vancouver an expensive city.","coverage":1},{"start":218.96,"end":219.52,"text":"Also,","coverage":1},{"start":219.84,"end":222.18,"text":"when you have a beautiful place to live,","coverage":1},{"start":222.9,"end":225.06,"text":"a lot of people want to go there.","coverage":1},{"start":225.06,"end":227.9,"text":"This makes the city crowded.","coverage":1},{"start":229.16,"end":229.5,"text":"Actually,","coverage":1},{"start":229.96,"end":232.4,"text":"Vancouver has very bad traffic.","coverage":1},{"start":233.72,"end":234.24,"text":"Lastly,","coverage":1},{"start":234.62,"end":236.18,"text":"when you have a lot of parks,","coverage":1},{"start":236.98,"end":240.76,"text":"wild animals in the parks can sometimes be a problem.","coverage":1},{"start":241.7,"end":242.62,"text":"For example,","coverage":1},{"start":243.46,"end":249.12,"text":"Stanley Park gives information to people about what to do if they see a coyote.","coverage":1},{"start":249.98,"end":251.02,"text":"In my opinion,","coverage":1},{"start":251.48,"end":254.06,"text":"having coyotes in a city park is bad.","coverage":1},{"start":254.06,"end":255.56,"text":"Finally,","coverage":1},{"start":256.14,"end":262.5,"text":"while I think these disadvantages might mean that some people would not want to visit Vancouver,","coverage":1},{"start":263.46,"end":268.12,"text":"I personally feel that most people would enjoy Vancouver.","coverage":1},{"start":268.68,"end":277.08,"text":"In my opinion, being close to nature and having a healthy city are worth paying a little more money for.","coverage":1},{"start":277.08,"end":280.42,"text":"And a lot of people agree with this idea,","coverage":1},{"start":281.22,"end":286.28,"text":"because Vancouver is a very popular place to visit and live in.","coverage":1},{"start":287.56,"end":292.84,"text":"So I would recommend that people visit Vancouver and enjoy the many parks,","coverage":1},{"start":293.38,"end":294,"text":"the clean,","coverage":1},{"start":294.44,"end":297.24,"text":"healthy city and the interesting sights.","coverage":1}],"file":"a82c2f1f77fc5312f206.js","track":0,"media":"../assets/media/91c2d6e131422bd80badd663f3864731f37172b73aef2c380d0cec1a6cf488bc.mp3"}]};
window.SCHOOL_SOURCE_ANSWERS=[{"text":"1 Where is the city of Venice?Possible answer: Venice is in Italy.","slide":4,"shape":"15","bookPage":"16"},{"text":"2 What do you know about Venice?Possible answer: It has many canals.","slide":4,"shape":"17","bookPage":"16"},{"text":"3 Why do tourists like to visit old towns or cities like Venice?Possible answer: Tourists can enjoy old buildings and learn about the city's history.","slide":4,"shape":"21","bookPage":"16"},{"text":"1  The king lives in a large palace.","slide":11,"shape":"9","bookPage":"16"},{"text":"2  A canal is a river made by people.","slide":11,"shape":"10","bookPage":"16"},{"text":"3  A house can stand on stilts above the water.","slide":11,"shape":"11","bookPage":"16"},{"text":"4  A gondola carries visitors along canals in Venice.","slide":11,"shape":"12","bookPage":"16"},{"text":"5  Something made by people is man-made.","slide":11,"shape":"13","bookPage":"16"},{"text":"Exercise 2 What looks different?Possible answer: There are waterways between the buildings. People can travel by boat.","slide":14,"shape":"15","bookPage":"16"},{"text":"What might the video discuss?Possible answer: It may explain the canals, old buildings and boats.","slide":14,"shape":"17","bookPage":"16"},{"text":"1 There are a lot of canals and bridges.True.","slide":18,"shape":"7","bookPage":"17"},{"text":"2 Most of the islands between the canals are big.False. The islands are little.","slide":18,"shape":"20","bookPage":"17"},{"text":"3 Today, Venice is important for art and businesses.False. Venice was important for art and businesses in the past.","slide":18,"shape":"22","bookPage":"17"},{"text":"4 People know Venice as a popular tourist centre.True.","slide":19,"shape":"7","bookPage":"17"},{"text":"5 The Grand Canal is the smallest canal in Venice.False. The Grand Canal is the largest canal in Venice.","slide":19,"shape":"20","bookPage":"17"},{"text":"6 The Grand Canal is a man-made river.True.","slide":19,"shape":"22","bookPage":"17"},{"text":"7 Another name for Venice is “The City of Boats”.False. Another name for Venice is “The City of Bridges”.","slide":20,"shape":"19","bookPage":"17"},{"text":"1 What does Venice have instead of busy roads?Answer: Canals.","slide":23,"shape":"7","bookPage":"17"},{"text":"2 What don’t you see on them?Answer: Cars.","slide":23,"shape":"19","bookPage":"17"},{"text":"3 What is the name of the special boats in the video?Answer: Gondolas.","slide":23,"shape":"21","bookPage":"17"},{"text":"4 What are palaces and other buildings in Venice built on?Answer: Stilts.","slide":24,"shape":"7","bookPage":"17"},{"text":"5 What was the Ca’ d’Oro palace decorated with?Answer: Gold.","slide":24,"shape":"19","bookPage":"17"},{"text":"6 What is the Rialto Bridge made of?Answer: Stone.","slide":24,"shape":"21","bookPage":"17"},{"text":"1  There are 117 islands between the canals and 400 bridges in Venice.","slide":26,"shape":"8","bookPage":"17"},{"text":"2  The Grand Canal is more than two miles long.","slide":26,"shape":"9","bookPage":"17"},{"text":"3  For nearly 300 years, you could only cross the Grand Canal on the Rialto\nBridge.","slide":26,"shape":"10","bookPage":"17"},{"text":"4  A gondola ride usually takes 30 minutes.","slide":26,"shape":"11","bookPage":"17"},{"text":"5  The palace was built in the 15 th century.","slide":26,"shape":"12","bookPage":"17"},{"text":"1 Why do you think the speaker says this?Possible answer: The speaker thinks the ride is a wonderful way to see Venice.","slide":28,"shape":"15","bookPage":"17"},{"text":"2 Do you agree with this opinion? Why / Why not?Possible answer: I agree because I would enjoy seeing the palaces from the water.","slide":28,"shape":"17","bookPage":"17"},{"text":"1 What do you think it is like to live in Venice?Possible answer: The views would be beautiful, but travelling by boat every day might be difficult.","slide":30,"shape":"15","bookPage":"17"},{"text":"2 Does your hometown or country have any interesting canals, rivers or roads?Possible answer: The Grand Canal in China connects many places. I would like to see part of it.","slide":30,"shape":"17","bookPage":"17"},{"text":"e  cave  (n) a large hole in the side of a mountain or under the ground","slide":43,"shape":"8","bookPage":"18"},{"text":"f  ancient  (adj) from a long time ago; very old","slide":43,"shape":"9","bookPage":"18"},{"text":"g  apartment  (n) a room or set of rooms where somebody lives, in a big building","slide":43,"shape":"10","bookPage":"18"},{"text":"h  capital  (n) the most important city in a country or state, where the government is","slide":43,"shape":"11","bookPage":"18"},{"text":"You are going to listen to a podcast about homes around the world. Look at the photos. What do you think you will learn about homes?Possible answer: I think we will learn where people live in unusual homes.","slide":47,"shape":"19","bookPage":"19"},{"text":"a / b: caves and rock; unusual homes","slide":48,"shape":"9","bookPage":"19"},{"text":"c: bridge       d: stilts","slide":49,"shape":"9","bookPage":"19"},{"text":"/eɪ/\n/ɒ/\n/ɪ/\n/ʌ/\nplace\nhot\nquick\nup\nancient, cave, strange\nrock\nbridge, stilts\n","slide":53,"shape":"18","bookPage":"20"},{"text":"/eɪ/\n/ɒ/\n/ɪ/\n/ʌ/\nplace\nhot\nquick\nup\nsay\nlong\nbuilt\nhundreds, under","slide":54,"shape":"17","bookPage":"20"},{"text":"/eɪ/\n/ɒ/\n/ɪ/\n/ʌ/\nplace\nhot\nquick\nup\nhate, Kate\ncot, not\nhit, kit\ncut, hut","slide":55,"shape":"19","bookPage":"20"},{"text":"1 The speakers on the podcast areAnswer: a Two world travellers.","slide":60,"shape":"16","bookPage":"21"},{"text":"2 The main topic of the podcast isAnswer: b Unusual places where people live.","slide":60,"shape":"18","bookPage":"21"},{"text":"1  Flowers grow in the soil.","slide":62,"shape":"8","bookPage":"21"},{"text":"2  Be careful near the edge of the cliff.","slide":62,"shape":"9","bookPage":"21"},{"text":"3  We put our bags on the ground.","slide":62,"shape":"10","bookPage":"21"},{"text":"(3) 1,000 kilometres west of Beijing.","slide":64,"shape":"10","bookPage":"21"},{"text":"Cappadocia is in (4) Anatolia, in central Türkiye.","slide":64,"shape":"11","bookPage":"21"},{"text":"Cappadocia facts: caves formed about (5) 8,000 years ago.","slide":64,"shape":"12","bookPage":"21"},{"text":"The Ponte Vecchio is in (6) Florence, Italy.","slide":66,"shape":"8","bookPage":"21"},{"text":"Ponte Vecchio facts: built in (7) 1345.","slide":66,"shape":"9","bookPage":"21"},{"text":"Chile is in (8) South America.","slide":66,"shape":"10","bookPage":"21"},{"text":"Stilt house facts: built on lakes and (9) the edge of the sea.","slide":66,"shape":"11","bookPage":"21"},{"text":"(10) Hundreds of people live there.","slide":66,"shape":"12","bookPage":"21"},{"text":"New informationPossible answer: I learned that some people live in houses on stilts in Chile.","slide":68,"shape":"15","bookPage":"21"},{"text":"A question I still havePossible answer: I would like to know more about the accident that destroyed the older bridge.","slide":68,"shape":"17","bookPage":"21"},{"text":"8. [S04] Vancouver has little room for new buildings because it lies between the mountains and the ocean.","slide":71,"shape":"5","bookPage":null},{"text":"9. [S04] Besides high costs and crowds, the speaker identifies bad traffic as a problem.","slide":71,"shape":"8","bookPage":null},{"text":"17. [S04] Why does the speaker connect parks with expensive housing?\nA. They require residents to buy land for each visit.\nB. They encourage people to build larger houses.\nC. They leave less land available for housing.","slide":72,"shape":"5","bookPage":null},{"text":"18. [S04] What concern does the speaker have about coyotes?\nA. Visitors need to bring food for the animals.\nB. Visitors have too few chances to see animals.\nC. Visitors may need advice about meeting wild animals.","slide":73,"shape":"5","bookPage":null},{"text":"24. [S04] Which TWO pressures on housing space are identified?\nA. New farmland surrounding the centre.\nB. The city's position between mountains and ocean.\nC. The disappearance of all visitors.\nD. Land used by parks.\nE. A ban on every building outside the city.","slide":74,"shape":"5","bookPage":null},{"text":"1  Our village is located near the sea.","slide":84,"shape":"9","bookPage":"25"},{"text":"2  The bus is slow because there is a lot of traffic.","slide":84,"shape":"10","bookPage":"25"},{"text":"3  This area of the city has many shops.","slide":84,"shape":"11","bookPage":"25"},{"text":"4  Trees grow close together in the woods.","slide":84,"shape":"12","bookPage":"25"},{"text":"5  We swam in the lake.","slide":84,"shape":"13","bookPage":"25"},{"text":"6  The open, grassy field is a good place for a picnic.","slide":84,"shape":"14","bookPage":"25"},{"text":"Exercise 2 What will the speaker discuss?Possible answer: The speaker may discuss a park near a city. I can see trees and water.","slide":87,"shape":"13","bookPage":"25"},{"text":"Listen to the lecture. What is its main idea?History and the advantages and disadvantages of Vancouver, Canada.","slide":90,"shape":"16","bookPage":"26"},{"text":"Advantages\nDisadvantages\nLots of gardens, walking paths, trees and animals.Cleaner air and places to walk.Easy access to nature.\nLess space for housing.Expensive, crowded city with bad traffic.Wild animals can sometimes be a problem (e.g. coyotes).","slide":91,"shape":"17","bookPage":"26"},{"text":"A possible responsePossible answer: I agree that parks give people places to walk. I don’t agree that wild animals are always a problem. I enjoy seeing animals in nature.","slide":93,"shape":"13","bookPage":"26"},{"text":"4 Finally, while I think these disadvantages might mean that some people would not want to visit Vancouver, …Opinion.","slide":96,"shape":"7","bookPage":"27"},{"text":"5 … I personally feel that most people would enjoy Vancouver.Opinion.","slide":96,"shape":"21","bookPage":"27"},{"text":"6 In my opinion, being close to nature and having a healthy city are worth paying a little more money for.Opinion.","slide":96,"shape":"23","bookPage":"27"},{"text":"1 Obviously, Stanley Park is a large park.Fact.","slide":99,"shape":"7","bookPage":"27"},{"text":"2 In fact, because it is located in the city of Vancouver, it is the third largest urban park in North America.Fact.","slide":99,"shape":"21","bookPage":"27"},{"text":"3 As we know, lots of trees help clean the city air.Fact.","slide":99,"shape":"23","bookPage":"27"},{"text":"Which tense is often used to give facts?The present simple.","slide":102,"shape":"2","bookPage":"27"},{"text":"General facts\nOpinions\nObviously\nI think\nIn fact\nI personally feel\nAs we know\nIn my opinion","slide":103,"shape":"16","bookPage":"27"},{"text":"1 Vancouver has the best parts of green forests and city life.Answer: Opinion.","slide":105,"shape":"7","bookPage":"28"},{"text":"2 It has many gardens, walking paths, trees and even animals such as bald eagles, coyotes and seals.Answer: Fact.","slide":105,"shape":"15","bookPage":"28"},{"text":"3 At the first city meeting, the people of Vancouver asked the national government to give the city 1,000 acres to use as a park.Answer: Fact.","slide":105,"shape":"17","bookPage":"28"},{"text":"4 It is one of the most beautiful cities in the world.Answer: Opinion.","slide":106,"shape":"14","bookPage":"28"},{"text":"An opinionPossible answer: I personally feel that a city with many parks is a good place to live.","slide":108,"shape":"15","bookPage":"28"},{"text":"A factual statementPossible answer: Vancouver is in Canada.","slide":108,"shape":"17","bookPage":"28"},{"text":"1 agree agreed","slide":115,"shape":"11","bookPage":"22"},{"text":"2 is / are was / were","slide":115,"shape":"18","bookPage":"22"},{"text":"3 drive drove","slide":115,"shape":"20","bookPage":"22"},{"text":"4 go went","slide":115,"shape":"7","bookPage":"22"},{"text":"5 shop shopped","slide":115,"shape":"9","bookPage":"22"},{"text":"6 sit sat","slide":116,"shape":"17","bookPage":"22"},{"text":"1 Years ago, people lived in boats on the river.","slide":118,"shape":"11","bookPage":"23"},{"text":"2 On Tuesday, we walked in the park.","slide":118,"shape":"18","bookPage":"23"},{"text":"3 I did not call / didn’t call my sister last week.","slide":118,"shape":"20","bookPage":"23"},{"text":"4 They stayed at a hotel by the sea.","slide":118,"shape":"7","bookPage":"23"},{"text":"5 He tried to relax every day.","slide":118,"shape":"9","bookPage":"23"},{"text":"A possible set of holiday sentencesPossible answer: I went to France. I stayed with a friend. I tried a new kind of food.","slide":121,"shape":"15","bookPage":"23"},{"text":"A possible responsePossible answer: I think sentence 2 is false. You stayed in a hotel.","slide":121,"shape":"17","bookPage":"23"},{"text":"1 Yasemin studied in Japan. (Where?)Answer: Where did Yasemin study?","slide":126,"shape":"7","bookPage":"23"},{"text":"2 Fahd travelled to Mumbai by train. (How?)Answer: How did Fahd travel to Mumbai?","slide":126,"shape":"18","bookPage":"23"},{"text":"3 The rain stopped at 9:30. (What time?)Answer: What time did the rain stop?","slide":126,"shape":"20","bookPage":"23"},{"text":"4 Carlos went to Egypt last week. (When?)Answer: When did Carlos go to Egypt?","slide":127,"shape":"17","bookPage":"23"},{"text":"5 They were happy because they were on holiday. (Why?)Why were they happy?","slide":127,"shape":"19","bookPage":"23"},{"text":"A place you liked as a childPossible answer: A: Where did you go in summer?B: I went to a lake. I swam there with my friends.","slide":129,"shape":"15","bookPage":"24"},{"text":"A negative statementPossible answer: A: Did you go there every day?B: No, I didn’t. I went there at weekends.","slide":129,"shape":"17","bookPage":"24"},{"text":"a  cheap","slide":142,"shape":"7","bookPage":"24"},{"text":"b  modern","slide":142,"shape":"8","bookPage":"24"},{"text":"c  crowded","slide":143,"shape":"7","bookPage":"24"},{"text":"d  rural","slide":143,"shape":"8","bookPage":"24"},{"text":"e  urban","slide":144,"shape":"7","bookPage":"24"},{"text":"f  popular","slide":144,"shape":"8","bookPage":"24"},{"text":"g  expensive","slide":145,"shape":"7","bookPage":"24"},{"text":"h  ancient","slide":145,"shape":"8","bookPage":"24"},{"text":"1 The city of Tokyo is a large urban area.","slide":147,"shape":"9","bookPage":"24"},{"text":"2 Many people like to visit Niagara Falls, so we can say that it is a popular place to go.","slide":147,"shape":"15","bookPage":"24"},{"text":"3 Norfolk is a county in England. It has very few cities and a lot of farms. It is one of the most rural places in the UK.","slide":147,"shape":"17","bookPage":"24"},{"text":"4 Hong Kong is a really expensive place to live. The cost of living there is very high.","slide":147,"shape":"7","bookPage":"24"},{"text":"A possible examplePossible answer: A: London is like this.B: Is it urban?A: Yes. It is a large city.","slide":149,"shape":"13","bookPage":"24"},{"text":"The streets were crowded.","slide":153,"shape":"6","bookPage":null},{"text":"I did not like the traffic.","slide":153,"shape":"10","bookPage":null},{"text":"The weather was perfect for a day out. We went to a lake. At the lake, we found a boat. We used the boat to cross the water.","slide":154,"shape":"6","bookPage":null},{"text":"There is a lake with trees around it. I think the park looks quiet and beautiful.","slide":155,"shape":"7","bookPage":null},{"text":"3. [S02] Native people did more than live there: they also traded in the area long before Europeans arrived.","slide":163,"shape":"5","bookPage":null},{"text":"4. [S02] The park request described an area of land, not a distance: 1,000 acres.","slide":163,"shape":"8","bookPage":null},{"text":"17. [S04] Which disadvantage comes from Vancouver's physical location?\nA. The mountains and ocean reduce the number of visitors.\nB. The mountains and ocean make park animals harder to see.\nC. The mountains and ocean limit the room for new buildings.","slide":164,"shape":"5","bookPage":null},{"text":"18. [S04] Which judgement is explicitly the speaker's opinion?\nA. Having coyotes in a city park is bad.\nB. Every coyote has attacked a visitor.\nC. The park gives no wildlife advice.","slide":165,"shape":"5","bookPage":null},{"text":"23. [S03] Which TWO cause-and-effect links are stated?\nA. Walking opportunities support health.\nB. Beaver Lake removes the need for parks.\nC. Trees help clean city air.\nD. Wildlife reduces every walking distance.\nE. More gardens make summers colder.","slide":166,"shape":"5","bookPage":null},{"text":"4. [L01] The national government refused the request for land. FALSE","slide":169,"shape":"5","bookPage":null},{"text":"5. [L01] The first city meeting lasted two hours. NOT GIVEN","slide":169,"shape":"8","bookPage":null},{"text":"6. [L02] Stanley Park is described as North America's largest urban park. FALSE","slide":170,"shape":"5","bookPage":null},{"text":"10. [L02] Beaver Lake is mentioned as a place people can enjoy. TRUE","slide":170,"shape":"8","bookPage":null},{"text":"16. A park's position in a ranking by size. L02","slide":171,"shape":"5","bookPage":null},{"text":"18. An explanation of why space for housing is limited. L03","slide":171,"shape":"8","bookPage":null},{"text":"The market did not open yesterday.","slide":178,"shape":"6","bookPage":null},{"text":"Why did the visitors leave?","slide":178,"shape":"10","bookPage":null},{"text":"We did not spend long shopping. We visited a busy market. The market was too crowded for us. So we left it and found a quiet cafe.","slide":179,"shape":"6","bookPage":null},{"text":"I bought some apples at this market. The seller put them in a paper bag. I liked the small stalls.","slide":180,"shape":"7","bookPage":null},{"text":"1 (b) Stanley Park gets about eight million visitors every year.","slide":187,"shape":"18","bookPage":"29"},{"text":"2 (c) You can enjoy nature, history, art and many events in the park.","slide":187,"shape":"20","bookPage":"29"},{"text":"3 (f) The park opened in 1888. It is more than 125 years old.","slide":187,"shape":"6","bookPage":"29"},{"text":"4 (d) The park is named after Lord Frederick Stanley, the Governor General of Canada in 1888.","slide":187,"shape":"8","bookPage":"29"},{"text":"5 (g) Vancouver cares for the park so people can enjoy it for many years.","slide":188,"shape":"18","bookPage":"29"},{"text":"6 (i) Stanley Park is the third largest urban park in North America. It is 4 km².","slide":188,"shape":"20","bookPage":"29"},{"text":"7 (j) Vancouver spends money to make it easier for everybody to walk and cycle in the park.","slide":188,"shape":"6","bookPage":"29"},{"text":"Why might you leave out a or h?Possible answer: Holiday opening hours and swimsuit hire are less useful for a general introduction.","slide":189,"shape":"19","bookPage":"29"},{"text":"Exercises 4 and 5 Choose and researchPossible answer: Possible topic: Kuang Si Waterfalls in Laos. Record the location and activities visitors can do.","slide":192,"shape":"15","bookPage":"30"},{"text":"What should your notes include?Possible answer: Facts: name, location, history or natural features.Opinions: reasons to visit and possible difficulties.","slide":192,"shape":"17","bookPage":"30"},{"text":"Plan for presentation\nInformation\n1  Introduction and general facts\nName of place? / Country? / Location?\nKuang Si Waterfalls, Laos.\n2  Facts\nHow old? / Who made it? / Other events?\nA natural place where visitors can swim and relax.\n3  Opinion (positives)\nInteresting? / Beautiful? / Why visit?\nI think the water is beautiful. I would enjoy relaxing there.\n4  Opinion (negatives)\nExpensive? / Too crowded? / Problems?\nGetting there might be difficult.\n5  Conclusion\nGood? Go or not?\nI would like to visit.","slide":195,"shape":"13","bookPage":"30"},{"text":"Exercise 1 Other ways to beginPossible answer: I think ...I guess ...It seems to me that ...","slide":197,"shape":"15","bookPage":"31"},{"text":"How certain are you?Possible answer: I’m sure that ...I’m not sure that ...I don’t think ...","slide":197,"shape":"17","bookPage":"31"},{"text":"A possible exchangeA: In my opinion, our town needs more bicycle lanes.B: Why do you think that?A: I personally feel that busy roads make cycling difficult.","slide":199,"shape":"12","bookPage":"31"},{"text":"1 General fact — d Europeans came to live in Vancouver in the 1800s.","slide":201,"shape":"9","bookPage":"31"},{"text":"2 Positives — a Parks give people places to walk, so they are healthier.","slide":201,"shape":"15","bookPage":"31"},{"text":"3 Negatives — b Having a lot of parks means there is less space to build houses.","slide":201,"shape":"17","bookPage":"31"},{"text":"4 Summary — c Life in Vancouver has more positives than negatives.","slide":201,"shape":"7","bookPage":"31"},{"text":"1 I’d like to talk about the city of Vancouver, in British Columbia, Canada.","slide":204,"shape":"9","bookPage":"32"},{"text":"2 First of all, let’s look at some of the positives.","slide":204,"shape":"17","bookPage":"32"},{"text":"3 I’d also like to talk about some disadvantages of parks in Vancouver.","slide":204,"shape":"19","bookPage":"32"},{"text":"4 Finally, while I think these disadvantages mean that some people would not want to visit Vancouver, I personally feel that most people would enjoy Vancouver.","slide":204,"shape":"7","bookPage":"32"},{"text":"Introduction\nI’d like to give you some information about …I’d like to talk about …\nMain section\n(additional points)\nFirst of all, …Because …For example, …The next topic is …\nConclusion\nLastly, …Finally, …","slide":208,"shape":"14","bookPage":"32"},{"text":"First of all, let’s look at some of the positives.","slide":211,"shape":"20","bookPage":"33"},{"text":"What makes a link?A final consonant sound connects to an initial vowel sound.","slide":211,"shape":"21","bookPage":"33"},{"text":"1 I’d like to give you some information about ...","slide":214,"shape":"14","bookPage":"33"},{"text":"2 Now let’s talk about ...","slide":214,"shape":"16","bookPage":"33"},{"text":"3 The next topic is ...","slide":214,"shape":"6","bookPage":"33"},{"text":"4 Finally, let’s look at ...","slide":214,"shape":"8","bookPage":"33"},{"text":"Exercise 10 A possible sentencePossible answer: I’d also like to talk about the history of the park.","slide":216,"shape":"13","bookPage":"33"},{"text":"IntroductionPossible answer: I’d like to talk about Kuang Si Waterfalls in Laos. Visitors can swim and relax there.I learned about this place from a photograph.","slide":222,"shape":"15","bookPage":"34"},{"text":"Main sectionPossible answer: First of all, I think the water is beautiful. I would enjoy spending time outdoors.","slide":222,"shape":"17","bookPage":"34"},{"text":"A possible disadvantageI’d also like to talk about a possible difficulty. Getting to the waterfalls might be difficult, so I would plan the journey carefully.","slide":223,"shape":"15","bookPage":"34"},{"text":"ConclusionFinally, I would like to visit because I enjoy natural places. I think the scenery would make the journey worthwhile.","slide":223,"shape":"17","bookPage":"34"},{"text":"What worked well?Possible answer: I liked your clear introduction and your description of the water.","slide":227,"shape":"15","bookPage":"34"},{"text":"What could improve?Possible answer: I think you can explain how visitors get there. You can also practise linking “talk about”.","slide":227,"shape":"17","bookPage":"34"},{"text":"Exercise 7 A question after listeningPossible answer: You said it might be difficult to get there. How would you travel there?","slide":231,"shape":"15","bookPage":"35"},{"text":"Exercise 8 Which place would you visit?Possible answer: I would choose the waterfalls because I like swimming and natural scenery.","slide":231,"shape":"17","bookPage":"35"},{"text":"I would like to talk about Green Lake.","slide":235,"shape":"6","bookPage":null},{"text":"In my opinion, this park is popular.","slide":235,"shape":"10","bookPage":null},{"text":"This is the place I go when I need a break. There is a park near my home. The park has a quiet path beside a lake. That path is why I think the park is a good place to relax.","slide":236,"shape":"6","bookPage":null},{"text":"I would stop at the cafe. Its tables are outside in the square. Visitors can look at the buildings while they sit. I think it would be a pleasant place for a break.","slide":237,"shape":"7","bookPage":null}];
